/**
 * Which conversation belongs to which project — and why that is not a name.
 *
 * THE APPROVED SCOPE IS SPECIFIC ABOUT THIS: the per-project governance thread is "keyed on an opaque
 * provider identifier held in governed project state — never on a conversation title, tab or window".
 * The reason is worth stating, because the convenient version is so much nicer to read. A title is
 * chosen by a human, editable at any moment, duplicable across projects, and — on the surfaces this
 * programme talks to — sometimes generated by a model from the first message. Keying governance state
 * on one means two projects can silently share a thread, or one project can lose its own, and the
 * failure looks like a renamed tab rather than like a governance breach.
 *
 * WHAT ISOLATION HAS TO MEAN HERE. The plan asks for distinct project ids, repository roots, thread
 * bindings and worker bindings, with deliberately mismatched bindings REFUSED and no cross-project
 * leakage of prompt, evidence, decision, session or repository facts. Three of those are properties of
 * a SET of bindings rather than of any one binding, so they cannot be checked one record at a time:
 * a binding that is perfectly well-formed on its own is exactly how a shared thread would look.
 *
 * Created in PROJECTOS-AUTONOMOUS-GATEKEEPER-LOOP1A.
 */

export const THREAD_BINDING_SCHEMA_VERSION = '1.0.0';

/** A project's governance conversation, as held in governed project state. */
export interface GovernanceThreadBinding {
  readonly schemaVersion?: unknown;
  readonly projectId?: unknown;
  /** Absolute path to the governed checkout. Two projects sharing one is not isolation. */
  readonly repositoryRoot?: unknown;
  /** The provider's own opaque identifier. Never a title, never a display name. */
  readonly providerThreadId?: unknown;
  /** The transport this thread lives on; a thread does not survive being moved between them. */
  readonly transportId?: unknown;
  readonly createdAt?: unknown;
}

export interface ThreadExpectations {
  readonly projectId: string;
  readonly repositoryRoot: string;
  readonly transportId: string;
}

/**
 * An opaque provider id.
 *
 * THE LENGTH RULE ALONE WAS NOT ENOUGH. `^[A-Za-z0-9_-]{12,128}$` accepted `projectos-governance`
 * and `owner_main_thread` — kebab-case and snake_case are exactly how a person names a conversation,
 * and both are made only of identifier characters. Requiring a DIGIT is what separates a provider's
 * generated id (`resp_7f3a9c2e5b81d40a`, `thread_abc123`) from a name someone typed, without
 * pretending to detect meaning.
 */
const OPAQUE_ID = /^(?=.*[0-9])[A-Za-z0-9_-]{12,128}$/;

/**
 * Things that are titles wearing an id's clothes.
 *
 * Kept even though `OPAQUE_ID` would reject all of these too, because the two produce DIFFERENT
 * messages and the difference is the useful part: "that looks like a conversation title" tells an
 * operator what they did wrong, where "that is not an opaque identifier" does not.
 */
const TITLE_SHAPED = /\s|["'()[\]{}<>,;:!?]/;

function text(v: unknown): string | null {
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null;
}

/** Compare paths without letting a trailing separator or letter case invent a second project. */
function normaliseRoot(p: string): string {
  return p.replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
}

/** Why this binding cannot be used for this run, or `[]` when it can. Pure — no I/O. */
export function checkThreadBinding(
  binding: GovernanceThreadBinding | null,
  expect: ThreadExpectations,
): readonly string[] {
  if (binding === null) {
    return [`project '${expect.projectId}' has no governance thread binding, so no conversation is its own`];
  }
  const e: string[] = [];

  if (binding.schemaVersion !== THREAD_BINDING_SCHEMA_VERSION) {
    e.push(`thread binding schemaVersion is ${JSON.stringify(binding.schemaVersion)}, expected "${THREAD_BINDING_SCHEMA_VERSION}"`);
  }
  if (binding.projectId !== expect.projectId) {
    e.push(`thread binding is for project ${JSON.stringify(binding.projectId)}, not '${expect.projectId}'`);
  }
  if (binding.transportId !== expect.transportId) {
    e.push(
      `thread binding lives on transport ${JSON.stringify(binding.transportId)}, but this run uses ` +
        `'${expect.transportId}'; a conversation does not survive being moved between transports`,
    );
  }

  const root = text(binding.repositoryRoot);
  if (root === null) {
    e.push('thread binding names no repository root');
  } else if (normaliseRoot(root) !== normaliseRoot(expect.repositoryRoot)) {
    e.push(
      `thread binding is bound to repository ${root}, but this run's governed root is ` +
        `${expect.repositoryRoot}; the same project id in a different checkout is a different world`,
    );
  }

  // THE IDENTIFIER ITSELF. A title is refused before it can become governance state.
  const thread = text(binding.providerThreadId);
  if (thread === null) {
    e.push('thread binding names no provider thread id');
  } else if (TITLE_SHAPED.test(thread)) {
    e.push(
      `provider thread id ${JSON.stringify(thread)} looks like a conversation title rather than an opaque ` +
        'identifier; a title is renameable, duplicable and sometimes model-generated, so it cannot key governance state',
    );
  } else if (!OPAQUE_ID.test(thread)) {
    e.push(
      `provider thread id ${JSON.stringify(thread)} is not an opaque provider identifier ` +
        '(identifier characters only, at least 12 of them, and at least one digit — a name someone ' +
        'typed rarely has one)',
    );
  }

  if (text(binding.createdAt) === null) e.push('thread binding records no createdAt');

  return e;
}

export interface IsolationBinding {
  readonly projectId: string;
  readonly repositoryRoot: string;
  readonly providerThreadId: string;
}

/**
 * Cross-project leakage across the whole set of bindings.
 *
 * SET-LEVEL, BECAUSE THAT IS WHERE THE FAILURE LIVES. Every individual binding below can be
 * impeccable while two of them point at one conversation — and a shared conversation is a shared
 * context, which is how one project's evidence reaches another project's review.
 */
export function isolationProblems(bindings: readonly IsolationBinding[]): readonly string[] {
  const e: string[] = [];
  const byThread = new Map<string, string[]>();
  const byRoot = new Map<string, string[]>();
  const seenProjects = new Set<string>();

  for (const b of bindings) {
    // NORMALISED THE SAME WAY `checkThreadBinding` NORMALISES. That function compares through
    // `text()`, which trims; this one used to key the map on the raw value. Two bindings whose ids
    // differed only by surrounding whitespace therefore passed the per-binding check as the SAME
    // thread and passed the set-level check as two DIFFERENT ones — so two projects could share one
    // conversation with every check green. Any divergence between how a value is validated and how
    // it is compared is a hole; keeping both on `text()` is what closes it.
    const threadKey = text(b.providerThreadId) ?? '';
    const projectKey = text(b.projectId) ?? '';

    if (seenProjects.has(projectKey)) {
      e.push(`project '${projectKey}' has more than one governance thread binding; which one is authoritative is undefined`);
    }
    seenProjects.add(projectKey);

    const threadOwners = byThread.get(threadKey) ?? [];
    threadOwners.push(projectKey);
    byThread.set(threadKey, threadOwners);

    const rootKey = normaliseRoot(text(b.repositoryRoot) ?? '');
    const rootOwners = byRoot.get(rootKey) ?? [];
    rootOwners.push(projectKey);
    byRoot.set(rootKey, rootOwners);
  }

  for (const [thread, owners] of byThread) {
    if (owners.length > 1) {
      e.push(
        `governance thread ${thread} is shared by ${owners.join(', ')}; a shared conversation is a shared ` +
          'context, so one project\'s evidence would reach another project\'s review',
      );
    }
  }
  for (const [root, owners] of byRoot) {
    if (owners.length > 1) {
      e.push(`repository root ${root} is claimed by ${owners.join(', ')}; two projects cannot govern one checkout`);
    }
  }
  return e;
}
